const rad = Math.PI / 180;
const dist = (la1, lo1, la2, lo2) => {
  const a = Math.sin(((la2 - la1) * rad) / 2) ** 2 + Math.cos(la1 * rad) * Math.cos(la2 * rad) * Math.sin(((lo2 - lo1) * rad) / 2) ** 2;
  return 2 * Math.asin(Math.sqrt(a));
};

export function onRequestGet({ request }) {
  const cf = request.cf || {};
  const lat = parseFloat(cf.latitude);
  const lon = parseFloat(cf.longitude);
  const headers = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'private, max-age=3600' };
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return new Response(JSON.stringify({}), { headers });
  let best = null;
  let bd = Infinity;
  for (const a of AIRPORTS) {
    const d = dist(lat, lon, a[1], a[2]);
    if (d < bd) { bd = d; best = a; }
  }
  const [icao, alat, alon, name, city, cc, iata] = best;
  return new Response(JSON.stringify({
    you: { lat: Math.round(lat * 100) / 100, lon: Math.round(lon * 100) / 100, city: cf.city || '' },
    airport: { icao, lat: alat, lon: alon, name, city, cc, iata },
  }), { headers });
}
